function addPiggieHub() {
    const drawer = document.querySelector('.mainDrawer .scrollContainer, .mainDrawer');
    if (!drawer || drawer.querySelector('.ptv-hub')) return;

    const hub = document.createElement('div');
    hub.className = 'ptv-hub';

    hub.innerHTML = `
        <div class="ptv-hub-title">Piggie Hub</div>

        <a class="ptv-hub-link" href="https://request.piggietv.com" target="_blank" rel="noopener">
            <img class="ptv-icon ptv-sidebar-icon" src="/assets/icons/request.svg" alt="">
            <span>Requests</span>
        </a>

        <a class="ptv-hub-link" href="https://music.piggietv.com" target="_blank" rel="noopener">
            <img class="ptv-icon ptv-sidebar-icon" src="/assets/icons/music.svg" alt="">
            <span>Music</span>
        </a>

        <a class="ptv-hub-link" href="https://books.piggietv.com" target="_blank" rel="noopener">
            <img class="ptv-icon ptv-sidebar-icon" src="/assets/icons/books.svg" alt="">
            <span>Books</span>
        </a>
    `;

    drawer.appendChild(hub);
}
